    case SENSOR_REPLAY_DETECTED:
        return "收到重复的传感器数据";
    case SENSOR_CAPABILITY_UNSUPPORTED:
        return "传感器不支持所需功能";
    case SENSOR_COMMAND_UNSUPPORTED:
        return "传感器命令不支持";
    case SENSOR_ARGUMENT_REJECTED:
        return "传感器不接受当前参数";
    case SENSOR_MODE_MISMATCH:
        return "传感器测量模式不一致";
    case SENSOR_MODE_NOT_ALLOWED:
        return "传感器当前模式不允许操作";
