/**
 * @brief 请求主循环执行一次屏幕刷新，不在中断中直接绘制 OLED。
 */
void Display_RequestRefresh(void)
{
    display_refresh_pending = true;
}

/**
 * @brief 按页面清屏策略清除下一次绘制涉及的 OLED 区域。
 */
static bool Display_ClearBeforeDraw(void)
{
    if (display_recover_before_draw) {
        return Display_PerformRecovery();
    }
    return OLED_Clear() == HAL_OK;
}

/**
 * @brief 请求一轮新的 OLED 硬恢复，并重置该轮连续失败计数。
 */
static void Display_RequestRecovery(void)
{
    display_recover_attempt_count = 0U;
    display_recover_requested = true;
}

/**
 * @brief 执行一次 OLED 硬恢复，并在失败时安排不超过上限的后续重试。
 * @return true 表示本次硬恢复成功；false 表示失败，本帧不得继续绘制或提交。
 */
static bool Display_PerformRecovery(void)
{
    HAL_StatusTypeDef status = OLED_RecoverAndClear();

    /* 本次恢复产生的 SPI 错误已经在底层累计，立即确认计数，避免同一错误绕过重试上限。 */
    display_last_spi_error_count = OLED_GetSpiErrorCount();
    if (status == HAL_OK) {
        display_recover_attempt_count = 0U;
        display_recover_requested = false;
        return true;
    }

    if (display_recover_attempt_count < DISPLAY_RECOVER_MAX_ATTEMPTS) {
        display_recover_attempt_count++;
    }
    display_last_recover_tick = HAL_GetTick();
    display_recover_requested =
        (display_recover_attempt_count < DISPLAY_RECOVER_MAX_ATTEMPTS);
    return false;
}

/**
 * @brief 主动恢复、SPI 错误计数变化或周期到期时，要求下一帧恢复 OLED 状态。
 * @return true 表示收到主动恢复请求、OLED SPI 累计错误数发生变化，或周期恢复时限已到；false 表示本帧无需重新初始化 OLED 绘制状态。
 */
static bool Display_ShouldRecoverBeforeDraw(void)
{
    uint32_t now = HAL_GetTick();
    uint32_t spi_error_count = OLED_GetSpiErrorCount();

    if (display_recover_requested) {
        display_recover_requested = false;
        display_last_recover_tick = now;
        return true;
    }

    /* OLED SPI 累计错误数一旦增加，下一帧立即执行恢复；不能继续等待周期性恢复窗口。 */
    if (spi_error_count != display_last_spi_error_count) {
        display_last_spi_error_count = spi_error_count;
        display_recover_attempt_count = 0U;
        display_last_recover_tick = now;
        return true;
    }

    if ((now - display_last_recover_tick) >= DISPLAY_RECOVER_INTERVAL_MS) {
        display_recover_attempt_count = 0U;
        display_last_recover_tick = now;
        return true;
    }

    return false;
}

/**
 * @brief 记录显示帧开始时的 SPI 错误计数，供帧结束时判断本次绘制是否无新增错误。
 * @return 返回进入本次显示帧时的 OLED SPI 累计错误计数快照；帧结束时与新计数比较。
 */
static uint32_t Display_BeginFrame(void)
{
    return OLED_GetSpiErrorCount();
}

/**
 * @brief 清除本次恢复标记；若绘制期间无新增 SPI 错误，则记录逻辑显示帧完成。
 *
 * @param frame_spi_error_start 本帧开始绘制前读取的 OLED SPI 累计错误计数快照；结束时与当前计数比较，用于判断绘制期间是否新增传输错误。
 */
static void Display_FinishFrame(uint32_t frame_spi_error_start)
{
    display_recover_before_draw = false;
    /* 只有本帧绘制期间没有新增 SPI 错误，才更新影子显存 CRC 并推进完整刷新序号。 */
    if (OLED_GetSpiErrorCount() == frame_spi_error_start) {
        OLED_MarkFrameComplete();
    }
}

/**
 * @brief 前景页绘制前重置状态页局部刷新缓存，并按需恢复 OLED。
 *
 * @param frame_spi_error_start 输出前景绘制开始时的 OLED SPI 累计错误计数，供帧结束时判断是否新增传输错误。
 * @return true 表示可以继续绘制；false 表示 OLED 恢复失败，本帧必须停止。
 */
static bool Display_PrepareForForegroundDraw(uint32_t *frame_spi_error_start)
{
    bool should_recover;

    if (frame_spi_error_start == NULL) {
        return false;
    }
    *frame_spi_error_start = Display_BeginFrame();

    /* 菜单、确认页等前景界面会覆盖整屏，回到状态页时不能继续用状态页局部刷新缓存。 */
    display_status_full_redraw_required = true;

    if (display_screen_off_active) {
        OLED_DisplayOn();
        Display_RequestRecovery();
        display_screen_off_active = false;
    }

    should_recover = Display_ShouldRecoverBeforeDraw();
    display_recover_before_draw = false;
    if (should_recover && !Display_PerformRecovery()) {
        return false;
    }

    return true;
}

/**
 * @brief 执行确认键或返回键长按动作，并提交对应前景绘制帧。
 *
 * @param long_press_key 长按按键。
 */
static void Display_ProcessLongPressAction(uint8_t long_press_key)
{
    if (long_press_key == LONG_PRESS_KEY_SURE) {
        uint32_t frame_spi_error_start;

        if (!Display_PrepareForForegroundDraw(&frame_spi_error_start)) {
            return;
        }
        FlagofTankOpera = true;
        Display_RecordMenuActivity(HAL_GetTick());
        useKey();
        keymenu[KEYNUM_IF_ENTER_MAINMENU].execute_opera();
        Display_FinishFrame(frame_spi_error_start);
    } else if (long_press_key == LONG_PRESS_KEY_BACK) {
        bool prepared = false;
        uint32_t frame_spi_error_start = 0U;

        /* 与长按确认进菜单一致：先进入确认页，确认键再执行对应动作。 */
        if (Display_CanEnterCancelMeasurementConfirm()) {
            if (!Display_PrepareForForegroundDraw(&frame_spi_error_start)) {
                return;
            }
            prepared = true;
        }
        if (Display_EnterCancelMeasurementConfirm()) {
            Display_RecordMenuActivity(HAL_GetTick());
            Display_FinishFrame(frame_spi_error_start);
        } else if (prepared) {
            display_recover_before_draw = false;
        }
    }
}

/**
 * @brief 主循环中优先处理长按动作，再依次消费普通按键事件。
 */
static void Display_ProcessPendingInput(void)
{
    uint8_t keypress;
    uint8_t long_press_key = Display_TakePendingLongPressAction();

    if (long_press_key != LONG_PRESS_KEY_NONE) {
        Display_ProcessLongPressAction(long_press_key);
        return;
    }

    do {
        keypress = Display_TakePendingKey();
        if ((keypress != 0U) && (FlagofTankOpera == true)) {
            bool prepared = false;
            uint32_t frame_spi_error_start = 0U;

            if (DisplayTankOpera_CanProcessKey(keypress)) {
                if (!Display_PrepareForForegroundDraw(&frame_spi_error_start)) {
                    return;
                }
                prepared = true;
            }
            if (KeyProcess(keypress)) {
                Display_RecordMenuActivity(HAL_GetTick());
                Display_FinishFrame(frame_spi_error_start);
            } else if (prepared) {
                display_recover_before_draw = false;
            }
        }
    } while (keypress != 0U);
}

/**
 * @brief 记录菜单最近一次有效交互时间。
 *
 * @param now 当前 HAL tick。该值单位为 ms，用于记录最近菜单操作时间并计算状态页自动恢复等待时间。
 * @note 仅在主循环处理菜单进入或有效按键后调用，不在中断中修改页面状态。
 */
static void Display_RecordMenuActivity(uint32_t now)
{
    display_menu_last_activity_tick = now;
}

/**
 * @brief 菜单长时间无操作时自动退回状态页。
 * @note 电机运行监控、扭力等待等业务等待页不参与普通菜单空闲退出。
 */
static void Display_ProcessMenuIdleExit(void)
{
    uint32_t now;

    if (!DisplayTankOpera_CanIdleExit()) {
        display_menu_last_activity_tick = HAL_GetTick();
        return;
    }

    now = HAL_GetTick();
    if ((uint32_t)(now - display_menu_last_activity_tick) < DISPLAY_MENU_IDLE_EXIT_MS) {
        return;
    }

    exitTankOpera();
    Display_ClearPendingKeys();
    Display_RecordMenuActivity(now);
    Display_RequestRefresh();
}

/**
 * @brief 处理显示刷新、按键事件和状态页增量更新。
 */
void Display_Task(void)
{
    Display_UpdateLongPressReleaseGuard();
    Display_ProcessPendingInput();
    Display_ProcessMenuIdleExit();

    if (!display_refresh_pending && Display_ShouldRequestStatusHighlightRefresh()) {
        display_refresh_pending = true;
    }

    if (display_refresh_pending) {
        uint32_t start_tick = HAL_GetTick();
        display_refresh_pending = false;
        RefreshScreen();
        display_last_refresh_ms = HAL_GetTick() - start_tick;
        /* 完整刷新耗时超过门限时累计超时次数，供显示性能诊断；该统计不在此处中断当前页面流程。 */
        if (display_last_refresh_ms > DISPLAY_REFRESH_TIMEOUT_MS) {
            display_refresh_timeout_count++;
        }
    }
}

/**
 * @brief 将三段 MAC 快照格式化为两行十六进制文本。
 *
 * @param status 已经完成配对结果和 MAC 有效性校验的无线状态快照。
 * @param line1 用于返回无线 MAC 地址前半段显示文字的定长缓存。
 * @param line2 用于返回无线 MAC 地址后半段显示文字的定长缓存。
 */
static void Display_FormatWirelessPairingMac(const volatile WirelessPairingStatus *status,
                                             char line1[9],
                                             char line2[9])
{
    uint32_t mac_high = status->mac_high;
    uint32_t mac_mid = status->mac_mid;
    uint32_t mac_low = status->mac_low;

    snprintf(line1, 9, "%02lX:%02lX:%02lX",
             (unsigned long)((mac_high >> 8) & 0xFFU),
             (unsigned long)(mac_high & 0xFFU),
             (unsigned long)((mac_mid >> 8) & 0xFFU));
    snprintf(line2, 9, "%02lX:%02lX:%02lX",
             (unsigned long)(mac_mid & 0xFFU),
             (unsigned long)((mac_low >> 8) & 0xFFU),
             (unsigned long)(mac_low & 0xFFU));
}

/**
 * @brief 格式化读取部件参数页的连接从机蓝牙 MAC。
 *
 * @param status 无线连接状态。
 * @param line 输出显示文本。
 * @param line_size 输出缓冲区长度。
 */
static void Display_FormatWirelessConnectionMacCompact(const volatile WirelessPairingStatus *status,
                                                       char *line,
                                                       size_t line_size)
{
    uint32_t mac_high;
    uint32_t mac_mid;
    uint32_t mac_low;

    if ((status == NULL) || (line == NULL) || (line_size == 0U)) {
        return;
    }

    mac_high = status->mac_high;
    mac_mid = status->mac_mid;
    mac_low = status->mac_low;
    snprintf(line,
             line_size,
             "MAC:%02lX%02lX%02lX%02lX%02lX%02lX",
             (unsigned long)((mac_high >> 8) & 0xFFU),
             (unsigned long)(mac_high & 0xFFU),
             (unsigned long)((mac_mid >> 8) & 0xFFU),
             (unsigned long)(mac_mid & 0xFFU),
             (unsigned long)((mac_low >> 8) & 0xFFU),
             (unsigned long)(mac_low & 0xFFU));
}

/**
 * @brief 按当前语言设置返回中文或英文显示文字。
 *
 * @param name_cn 当前语言为中文时返回的只读文字；允许为 NULL。
 * @param name_en 当前语言为英文时返回的只读文字；为空时回退到中文文字。
 * @return 返回按当前语言设置返回中文或英文显示文字对应的只读文本首地址；内容由当前输入或语言配置选择，调用方不得修改或释放。
 */
static const char *Display_SelectLanguageText(const uint8_t *name_cn, const uint8_t *name_en)
{
    if ((screen_parameter.language == LANGUAGE_ENGLISH) && (name_en != NULL)) {
        return (const char *)name_en;
    }

    return (const char *)name_cn;
}

/**
 * @brief 计算中英文标签绘制后占用的最后一行。
 *
 * @param name_cn 用于计算中文标签宽度的只读文字。
 * @param name_en 用于计算英文标签宽度的只读文字；为空时使用中文标签。
 * @return 返回中英文标签绘制后占用的最后一行的有效长度，单位字节；0 表示没有可供消费的数据。
 */
static uint8_t Display_GetLabelEndLine(const uint8_t *name_cn, const uint8_t *name_en)
{
    return Display_GetTextWidth(Display_SelectLanguageText(name_cn, name_en), 63U);
}

/**
 * @brief 把状态文字安全复制到固定长度的状态槽缓存。
 *
 * @param dest 状态文字的目标定长缓存。
 * @param src 待复制到状态槽的只读文字；NULL 按空字符串处理。
 */
static void Display_CopyStatusText(char dest[32], const char *src)
{
    uint8_t i;

    if (src == NULL) {
        dest[0] = '\0';
        return;
    }

    for (i = 0U; (src[i] != '\0') && (i < 31U); i++) {
        dest[i] = src[i];
    }
    dest[i] = '\0';
}

/**
 * @brief 向状态页快照追加一个有序显示槽；参数无效或容量已满时返回 NULL，成功后由调用方填入数值或文本。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 * @param id 编号。该值是 CPU3 状态页固定槽位标识，用于在快照中定位同一业务字段并执行全量或差量重绘。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param value_line 状态槽数值或文字在 OLED 上开始绘制的横向像素位置。
 * @return 成功时返回指向向状态页快照追加一个有序显示槽；参数无效或容量已满时返回 NULL，成功后由调用方填入数值或文本的指针；输入非法或未找到匹配项时返回 NULL。
 */
static DisplayStatusSlot *Display_AddStatusSlot(DisplayStatusSnapshot *snapshot,
                                                DisplayStatusSlotId id,
                                                uint8_t row,
                                                uint8_t value_line)
{
    DisplayStatusSlot *slot;

    if ((snapshot == NULL) || (snapshot->slot_count >= DISPLAY_STATUS_MAX_SLOTS)) {
        return NULL;
    }

    slot = &snapshot->slots[snapshot->slot_count];
    memset(slot, 0, sizeof(*slot));
    slot->id = id;
    slot->row = row;
    slot->value_line = value_line;
    snapshot->slot_count++;
    return slot;
}

/**
 * @brief 向状态页快照追加数值槽，并记录显示值、小数位和单位。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 * @param id 编号。该值是 CPU3 状态页固定槽位标识，用于在快照中定位同一业务字段并执行全量或差量重绘。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param value_line 状态槽数值或文字在 OLED 上开始绘制的横向像素位置。
 * @param value 待格式化并绘制到 OLED 的数值。
 * @param points 状态页数值槽的小数位数；后续绘制按该位数缩放和格式化 value。
 * @param unit 数值对应的工程单位文字。
 */
static void Display_AddValueStatusSlot(DisplayStatusSnapshot *snapshot,
                                       DisplayStatusSlotId id,
                                       uint8_t row,
                                       uint8_t value_line,
                                       int32_t value,
                                       uint8_t points,
                                       const uint8_t *unit)
{
    DisplayStatusSlot *slot = Display_AddStatusSlot(snapshot, id, row, value_line);

    if (slot != NULL) {
        slot->is_text = false;
        slot->value = value;
        slot->points = points;
        slot->unit = unit;
    }
}

/**
 * @brief 向状态页快照追加文本槽，并复制受长度限制的显示文本。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 * @param id 编号。该值是 CPU3 状态页固定槽位标识，用于在快照中定位同一业务字段并执行全量或差量重绘。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param value_line 状态槽数值或文字在 OLED 上开始绘制的横向像素位置。
 * @param text 待测量、排版或写入状态槽的 NUL 结尾显示文字；宽度计算同时处理 ASCII 与中文字节。
 */
static void Display_AddTextStatusSlot(DisplayStatusSnapshot *snapshot,
                                      DisplayStatusSlotId id,
                                      uint8_t row,
                                      uint8_t value_line,
                                      const char *text)
{
    DisplayStatusSlot *slot = Display_AddStatusSlot(snapshot, id, row, value_line);

    if (slot != NULL) {
        slot->is_text = true;
        Display_CopyStatusText(slot->text, text);
    }
}

/**
 * @brief 按 OLED 可用宽度拆分当前故障原因，并加入状态页文本槽。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 * @param now_page 页面。
 */
static void Display_AddErrorReasonStatusSlots(DisplayStatusSnapshot *snapshot, int now_page)
{
    const char *reason = Display_GetErrorReasonByCode(g_measurement.device_status.error_code);
    char first_line[32];
    uint8_t prefix_width = Display_GetTextWidth("故障:", 7U);
    uint8_t first_bytes = Display_GetFitTextBytes(reason, prefix_width);

    /* 当前页包含故障原因首行槽位时，只复制本行能够容纳的完整字节。 */
    if ((ValidParaDisArr[Para_ErrorReason][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_ErrorReason][PARA_PAGE])) {
        uint8_t i;

        for (i = 0U; (i < first_bytes) && (i < (sizeof(first_line) - 1U)); i++) {
            first_line[i] = reason[i];
        }
        first_line[i] = '\0';
        Display_AddTextStatusSlot(snapshot,
                                  DISPLAY_STATUS_SLOT_ERROR_REASON,
                                  (uint8_t)ValidParaDisArr[Para_ErrorReason][PARA_X],
                                  prefix_width,
                                  first_line);
    }

    /* 仅当原因仍有剩余文本且当前页分配了续行槽位时，才发布第二行故障原因。 */
    if ((ValidParaDisArr[Para_ErrorReasonMore][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_ErrorReasonMore][PARA_PAGE]) &&
        (reason[first_bytes] != '\0')) {
        Display_AddTextStatusSlot(snapshot,
                                  DISPLAY_STATUS_SLOT_ERROR_REASON_MORE,
                                  (uint8_t)ValidParaDisArr[Para_ErrorReasonMore][PARA_X],
                                  OLED_LINE8_1,
                                  &reason[first_bytes]);
    }
}

/**
 * @brief 根据当前状态页及数据有效性构建本页数值和文本槽。
 *
 * 函数先追加当前错误原因槽，再依据 ValidParaDisArr
 * 中每个项目的有效标志、所属页号和行坐标，为当前页选择性追加液位、水位、密度、温度、位置、扭力、扭力模块温度、传感器频率、电容、姿态角、罐高、无线 RSSI 和对端 MAC。
 * 数值来源随 snapshot->ctx 切换：结果页优先读取已经发布的测量结果，部件读取页使用调试快照；温度按内部偏移恢复为 0.01 ℃，长度保留 0.1 mm，密度保留两位小数，频率使用
 * Hz，RSSI 使用 dB。
 * 液位处于下盲区时显示“低于盲区”而不是伪造数值；扭力模块温度无效时显示“--.--”，RSSI 或 MAC 尚未确认时分别追加 N/A 文本槽。
 * 本函数只向 DisplayStatusSnapshot 追加用于后续全量或差量绘制的槽，不直接刷新 OLED；同一槽位编号用于让绘制层识别内容变化并清除旧区域。
 *
 * @param snapshot 当前结果页的可写状态快照；函数向其中追加带固定槽位编号的文字或数值项，供后续全量或差量 OLED 绘制。
 * @param now_page 当前待构建的结果页页号；仅追加 ValidParaDisArr 中 PARA_PAGE 与该值相等的项目。
 * @note 调用方必须传入已初始化且可继续追加槽位的 snapshot，并先完成 CalculateValidPara 页面布局；本函数不检查 snapshot 空指针。
 */
static void Display_AddCurrentPageValueStatusSlots(DisplayStatusSnapshot *snapshot, int now_page)
{
    uint8_t row;
    uint8_t line;
    uint32_t display_value = 0U;
    int display_position = 0;
    int display_frequency;
    int display_capacitance;
    int32_t torque_temperature_x100;

    Display_AddErrorReasonStatusSlots(snapshot, now_page);

    if (flagofoillevelvalid == true) {
        row = FlagofTotalTwoRow ? OLED_ROW4_3 : OLED_ROW4_2;
        line = Display_GetLabelEndLine((uint8_t*)"液位:", (uint8_t*)"Level:");
        if (Display_GetOilLevelValue(snapshot->ctx, &display_value) &&
            ((display_value == OILLEVELDOWNLIMIT) || (display_value == LEVEL_DOWNLIMIT))) {
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_OIL_LEVEL,
                                      row,
                                      line,
                                      Display_SelectLanguageText((uint8_t*)"低于盲区",
                                                                 (uint8_t*)"Below Blind"));
        } else {
            Display_AddValueStatusSlot(snapshot,
                                       DISPLAY_STATUS_SLOT_OIL_LEVEL,
                                       row,
                                       line,
                                       (int32_t)display_value,
                                       1U,
                                       (uint8_t*)"mm");
        }
    }

    if ((ValidParaDisArr[Para_Waterlevel][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_Waterlevel][PARA_PAGE]) &&
        Display_GetWaterLevelValue(snapshot->ctx, &display_value)) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_WATER_LEVEL,
                                   (uint8_t)ValidParaDisArr[Para_Waterlevel][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"水位:", (uint8_t*)"Water:"),
                                   (int32_t)display_value,
                                   1U,
                                   (uint8_t*)"mm");
    }

    if ((ValidParaDisArr[Para_AveDensity][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_AveDensity][PARA_PAGE]) &&
        Display_GetDensityValue(snapshot->ctx, &display_value)) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_DENSITY,
                                   (uint8_t)ValidParaDisArr[Para_AveDensity][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"密度:", (uint8_t*)"D:"),
                                   (int32_t)display_value,
                                   2U,
                                   (uint8_t*)"kg/m3");
    }

    if ((ValidParaDisArr[Para_AveTemperature][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_AveTemperature][PARA_PAGE]) &&
        Display_GetTemperatureValue(snapshot->ctx, &display_value)) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_TEMPERATURE,
                                   (uint8_t)ValidParaDisArr[Para_AveTemperature][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"温度:", (uint8_t*)"Temp:"),
                                   (int32_t)display_value - 20000,
                                   2U,
                                   (uint8_t*)"℃");
    }

    if ((ValidParaDisArr[Para_position][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_position][PARA_PAGE]) &&
        Display_GetPositionValue(snapshot->ctx, &display_position)) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_POSITION,
                                   (uint8_t)ValidParaDisArr[Para_position][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"位置:", (uint8_t*)"Pos:"),
                                   (int32_t)display_position,
                                   1U,
                                   (uint8_t*)"mm");
    }

    if ((ValidParaDisArr[Para_weight][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_weight][PARA_PAGE])) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_WEIGHT,
                                   (uint8_t)ValidParaDisArr[Para_weight][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"扭力:", (uint8_t*)"Torque:"),
                                   (int32_t)g_measurement.debug_data.current_weight,
                                   0U,
                                   (uint8_t*)" ");
    }

    if ((ValidParaDisArr[Para_torque_temperature][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_torque_temperature][PARA_PAGE])) {
        row = (uint8_t)ValidParaDisArr[Para_torque_temperature][PARA_X];
        line = Display_GetLabelEndLine((uint8_t*)"扭温:", (uint8_t*)"T.Temp:");
        if (Display_GetTorqueTemperatureX100(snapshot->ctx, &torque_temperature_x100)) {
            Display_AddValueStatusSlot(snapshot,
                                       DISPLAY_STATUS_SLOT_TORQUE_TEMPERATURE,
                                       row,
                                       line,
                                       torque_temperature_x100,
                                       2U,
                                       (uint8_t*)"℃");
        } else {
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_TORQUE_TEMPERATURE,
                                      row,
                                      line,
                                      "--.--");
        }
    }

    if ((ValidParaDisArr[Para_sensor_value][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_sensor_value][PARA_PAGE])) {
        display_frequency = (snapshot->ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
            ? (int)g_measurement.debug_data.frequency
            : GetOilSensorFrequencyForDisplay();
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_FREQUENCY,
                                   (uint8_t)ValidParaDisArr[Para_sensor_value][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"频率:", (uint8_t*)"Freq:"),
                                   (int32_t)display_frequency,
                                   0U,
                                   (uint8_t*)"Hz");
    }

    if ((ValidParaDisArr[Para_capacitance][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_capacitance][PARA_PAGE])) {
        display_capacitance = (snapshot->ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
            ? (int)g_measurement.debug_data.water_capacitance_x10
            : (int)(g_measurement.water_measurement.current_capacitance * 10.0f);
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_CAPACITANCE,
                                   (uint8_t)ValidParaDisArr[Para_capacitance][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"电容:", (uint8_t*)"Cap:"),
                                   (int32_t)display_capacitance,
                                   1U,
                                   NULL);
    }

    if ((ValidParaDisArr[Para_angle_x][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_angle_x][PARA_PAGE])) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_ANGLE_X,
                                   (uint8_t)ValidParaDisArr[Para_angle_x][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"X角:", (uint8_t*)"AngX:"),
                                   (int32_t)g_measurement.debug_data.angle_x,
                                   2U,
                                   (uint8_t*)"°");
    }

    if ((ValidParaDisArr[Para_angle_y][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_angle_y][PARA_PAGE])) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_ANGLE_Y,
                                   (uint8_t)ValidParaDisArr[Para_angle_y][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"Y角:", (uint8_t*)"AngY:"),
                                   (int32_t)g_measurement.debug_data.angle_y,
                                   2U,
                                   (uint8_t*)"°");
    }

    if ((ValidParaDisArr[Para_tankheight][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_tankheight][PARA_PAGE])) {
        Display_AddValueStatusSlot(snapshot,
                                   DISPLAY_STATUS_SLOT_TANK_HEIGHT,
                                   (uint8_t)ValidParaDisArr[Para_tankheight][PARA_X],
                                   Display_GetLabelEndLine((uint8_t*)"罐高:", (uint8_t*)"tankH:"),
                                   (int32_t)g_measurement.height_measurement.current_real_height,
                                   1U,
                                   (uint8_t*)"mm");
    }

    if ((ValidParaDisArr[Para_wireless_rssi][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_wireless_rssi][PARA_PAGE])) {
        if (g_measurement.wireless_pairing_status.rssi_valid != 0U) {
            Display_AddValueStatusSlot(snapshot,
                                       DISPLAY_STATUS_SLOT_WIRELESS_RSSI,
                                       (uint8_t)ValidParaDisArr[Para_wireless_rssi][PARA_X],
                                       Display_GetLabelEndLine((uint8_t*)"RSSI:", (uint8_t*)"RSSI:"),
                                       g_measurement.wireless_pairing_status.rssi,
                                       0U,
                                       (uint8_t*)"dB");
        } else {
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_WIRELESS_RSSI_NA,
                                      (uint8_t)ValidParaDisArr[Para_wireless_rssi][PARA_X],
                                      OLED_LINE8_1,
                                      "RSSI:N/A");
        }
    }

    if ((ValidParaDisArr[Para_wireless_mac][PARA_VALID] == true) &&
        (now_page == ValidParaDisArr[Para_wireless_mac][PARA_PAGE])) {
        const volatile WirelessPairingStatus *status = &g_measurement.wireless_pairing_status;

        if ((status->connection_valid != 0U) && (status->mac_valid != 0U)) {
            char mac_line[17];

            Display_FormatWirelessConnectionMacCompact(status, mac_line, sizeof(mac_line));
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_WIRELESS_MAC_COMPACT,
                                      (uint8_t)ValidParaDisArr[Para_wireless_mac][PARA_X],
                                      OLED_LINE8_1,
                                      mac_line);
        } else {
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_WIRELESS_MAC_NA,
                                      (uint8_t)ValidParaDisArr[Para_wireless_mac][PARA_X],
                                      OLED_LINE8_1,
                                      "MAC N/A");
        }
    }
}

/**
 * @brief 按配对结果和 MAC 有效性追加无线状态槽。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 */
static void Display_AddWirelessPairingSlots(DisplayStatusSnapshot *snapshot)
{
    const volatile WirelessPairingStatus *status = &g_measurement.wireless_pairing_status;

    if ((snapshot->state != STATE_WIRELESS_PAIRING_OVER) ||
        (status->result != WIRELESS_PAIRING_RESULT_SUCCESS) ||
        (status->mac_valid == 0U)) {
        if (snapshot->state == STATE_WIRELESS_PAIRING_OVER) {
            Display_AddTextStatusSlot(snapshot,
                                      DISPLAY_STATUS_SLOT_WIRELESS_MAC_NA,
                                      OLED_ROW4_2,
                                      OLED_LINE8_2,
                                      "MAC N/A");
        }
        return;
    }

    {
        char mac_line1[9];
        char mac_line2[9];

        Display_FormatWirelessPairingMac(status, mac_line1, mac_line2);
        Display_AddTextStatusSlot(snapshot,
                                  DISPLAY_STATUS_SLOT_WIRELESS_MAC_1,
                                  OLED_ROW4_3,
                                  OLED_LINE8_2,
                                  mac_line1);
        Display_AddTextStatusSlot(snapshot,
                                  DISPLAY_STATUS_SLOT_WIRELESS_MAC_2,
                                  OLED_ROW4_4,
                                  OLED_LINE8_2,
                                  mac_line2);
    }
}

/**
 * @brief 达到页面保持次数后推进多页状态索引。
 *
 * @param page_amount 当前状态页实际可轮换的页面总数；小于等于 1 时固定显示第 0 页，否则按保持刷新次数循环推进。
 */
static void Display_AdvanceStatusPage(int page_amount)
{
    if (page_amount <= 1) {
        display_status_page_index = 0;
        display_status_page_hold_count = 0U;
        return;
    }

    if (display_status_page_hold_count < (DISPLAY_STATUS_PAGE_HOLD_REFRESHES - 1U)) {
        display_status_page_hold_count++;
        return;
    }

    display_status_page_hold_count = 0U;
    display_status_page_index++;
    if (display_status_page_index >= page_amount) {
        display_status_page_index = 0;
    }
}

/**
 * @brief 采集设备状态、语言和当前页槽位，构建本次状态页渲染快照。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 */
static void Display_BuildStatusSnapshot(DisplayStatusSnapshot *snapshot)
{
    uint8_t lang;

    if (snapshot == NULL) {
        return;
    }

    memset(snapshot, 0, sizeof(*snapshot));
    snapshot->valid = true;
    snapshot->state = g_measurement.device_status.device_state;
    snapshot->error_code = g_measurement.device_status.error_code;
    snapshot->ctx = Display_GetResultContext(g_measurement.device_status.device_state);
    snapshot->protocol_compatible = IsCpu2ProtocolCompatible();
    snapshot->protocol_mismatch = IsCpu2ProtocolMismatch();
    lang = (uint8_t)screen_parameter.language;
    if (lang > LANGUAGE_ENGLISH) {
        lang = LANGUAGE_ENGLISH;
    }
    snapshot->language = lang;

    CalculateValidPara();
    if ((PageAmount <= 0) || (display_status_page_index >= PageAmount)) {
        display_status_page_index = 0;
        display_status_page_hold_count = 0U;
    }

    snapshot->page = display_status_page_index;
    snapshot->page_amount = PageAmount;
    snapshot->total_two_row = FlagofTotalTwoRow;

    if ((snapshot->state == STATE_WIRELESS_PAIRING) ||
        (snapshot->state == STATE_WIRELESS_PAIRING_OVER)) {
        Display_AddWirelessPairingSlots(snapshot);
    } else {
        Display_AddCurrentPageValueStatusSlots(snapshot, snapshot->page);
    }

    Display_AdvanceStatusPage(PageAmount);
}

/**
 * @brief 判断状态槽的标签、行号或布局参数是否发生变化。
 *
 * @param current 本次准备显示的当前状态页快照。
 * @param last 上一次保存的值、状态或快照。
 * @return true 表示两个槽位的 id、文本或数值类型、行号、数值列、小数位或单位中至少一项不同；false 表示上述全部布局字段完全一致。
 */
static bool Display_StatusSlotLayoutChanged(const DisplayStatusSlot *current,
                                            const DisplayStatusSlot *last)
{
    return (current->id != last->id) ||
           (current->is_text != last->is_text) ||
           (current->row != last->row) ||
           (current->value_line != last->value_line) ||
           (current->points != last->points) ||
           (current->unit != last->unit);
}

/**
 * @brief 比较两次快照的页面和槽位布局，判断是否需要全量重绘。
 *
 * @param current 本次准备显示的当前状态页快照。
 * @param last 上一次保存的值、状态或快照。
 * @return true 表示页面类型、槽位数量、槽位标识、行位置或文字/数值布局中至少一项发生变化；false 表示两份状态页快照的布局完全一致。
 */
static bool Display_StatusLayoutChanged(const DisplayStatusSnapshot *current,
                                        const DisplayStatusSnapshot *last)
{
    uint8_t i;

    if ((current == NULL) || (last == NULL) || !last->valid) {
        return true;
    }

    if ((current->state != last->state) ||
        (current->error_code != last->error_code) ||
        (current->ctx != last->ctx) ||
        (current->protocol_compatible != last->protocol_compatible) ||
        (current->protocol_mismatch != last->protocol_mismatch) ||
        (current->language != last->language) ||
        (current->total_two_row != last->total_two_row) ||
        (current->page != last->page) ||
        (current->page_amount != last->page_amount) ||
        (current->slot_count != last->slot_count)) {
        return true;
    }

    for (i = 0U; i < current->slot_count; i++) {
        if (Display_StatusSlotLayoutChanged(&current->slots[i], &last->slots[i])) {
            return true;
        }
    }

    return false;
}

/**
 * @brief 判断状态页是否需要重新采样运行数据。
 *
 * @param now 本次判断使用的当前系统节拍，单位 ms；调用方在同一轮处理内复用该快照，避免多次取时造成边界漂移。
 * @return true 表示需要按当前 g_measurement 生成新快照，false 表示仅允许恢复反白显示。
 */
static bool Display_ShouldSampleStatusData(uint32_t now)
{
    uint8_t lang = (uint8_t)screen_parameter.language;

    if (!display_status_active_snapshot.valid) {
        return true;
    }

    if (lang > LANGUAGE_ENGLISH) {
        lang = LANGUAGE_ENGLISH;
    }

    if ((display_status_active_snapshot.state != g_measurement.device_status.device_state) ||
        (display_status_active_snapshot.error_code != g_measurement.device_status.error_code) ||
        (display_status_active_snapshot.language != lang) ||
        (display_status_active_snapshot.protocol_compatible != IsCpu2ProtocolCompatible()) ||
        (display_status_active_snapshot.protocol_mismatch != IsCpu2ProtocolMismatch())) {
        return true;
    }

    return ((now - display_status_last_data_refresh_tick) >= DISPLAY_STATUS_DATA_REFRESH_MS);
}

/**
 * @brief 记录状态页最近一次按运行数据采样的节拍。
 *
 * @param now 本次判断使用的当前系统节拍，单位 ms；调用方在同一轮处理内复用该快照，避免多次取时造成边界漂移。
 */
static void Display_ResetStatusDataRefreshTick(uint32_t now)
{
    display_status_last_data_refresh_tick = now;
}

/**
 * @brief 按状态页快照重画单个数值或文本区域。
 *
 * @param slot 状态页显示项快照。
 * @param shift 非 0 时按反显方式绘制。
 */
static void Display_DrawStatusSlotValue(const DisplayStatusSlot *slot, uint8_t shift)
{
    if (slot == NULL) {
        return;
    }

    if (slot->is_text) {
        OledDisplayLineWords(slot->text, slot->value_line, slot->row, shift);
    } else {
        OledValueDisplay((int)slot->value,
                         slot->value_line,
                         slot->row,
                         shift,
                         slot->points,
                         (uint8_t *)slot->unit);
    }
}

/**
 * @brief 判断状态槽的显示值或有效性是否发生变化。
 *
 * @param current 本次准备显示的当前状态页快照。
 * @param last 上一次保存的值、状态或快照。
 * @return true 表示任一槽位指针为空、文本或数值类型不同、文本内容不同，或数值不同；false 表示两个有效槽位类型一致且对应文本或数值内容相同。
 */
static bool Display_StatusSlotValueChanged(const DisplayStatusSlot *current,
                                           const DisplayStatusSlot *last)
{
    if ((current == NULL) || (last == NULL) || (current->is_text != last->is_text)) {
        return true;
    }

    if (current->is_text) {
        return (strncmp(current->text, last->text, sizeof(current->text)) != 0);
    }

    return (current->value != last->value);
}

/**
 * @brief 按无符号节拍回绕规则判断一个时刻是否早于另一个时刻。
 *
 * @param left 区间左端值或左侧比较对象。
 * @param right 区间右端值或右侧比较对象。
 * @return true 表示 left 按 32 位节拍回绕规则早于 right；false 表示 left 已经到达或晚于 right。
 */
static bool Display_StatusTickBefore(uint32_t left, uint32_t right)
{
    return ((int32_t)(left - right) < 0);
}

/**
 * @brief 判断指定状态槽当前是否处于高亮保持期。
 *
 * @param slot 待检查的状态槽快照，提供高亮可见标志和高亮截止节拍。
 * @param now 本次判断使用的当前系统节拍，单位 ms；调用方在同一轮处理内复用该快照，避免多次取时造成边界漂移。
 * @return true 表示槽位指针有效、反白可见标志已置位，且当前时刻仍早于反白截止时刻；false 表示槽位为空、反白未启用，或保持时间已经到期。
 */
static bool Display_IsStatusHighlightActive(const DisplayStatusSlot *slot, uint32_t now)
{
    return ((slot != NULL) &&
            slot->highlight_visible &&
            Display_StatusTickBefore(now, slot->highlight_until_tick));
}

/**
 * @brief 清除指定状态槽上一次数值占用的 OLED 区域。
 *
 * @param slot 待清除的状态槽布局，提供数值起始列和所在 OLED 行。
 */
static void Display_ClearStatusSlotValueArea(const DisplayStatusSlot *slot)
{
    uint8_t width;

    if ((slot == NULL) || (slot->value_line > OLED_LINE8_END)) {
        return;
    }

    width = (uint8_t)(OLED_LINE8_END + 1U - slot->value_line);
    OLED_ClearArea(slot->value_line, slot->row, width, DISPLAY_VALUE_AREA_HEIGHT);
}

/**
 * @brief 检测槽位值变化并更新短时反白截止时间。
 *
 * @param current 本次准备显示的当前状态页快照。
 * @param last 上一次保存的值、状态或快照。
 */
static void Display_UpdateStatusHighlights(DisplayStatusSnapshot *current,
                                           const DisplayStatusSnapshot *last)
{
    uint8_t i;
    uint32_t now = HAL_GetTick();

    if ((current == NULL) || (last == NULL)) {
        return;
    }

    for (i = 0U; i < current->slot_count; i++) {
        DisplayStatusSlot *current_slot = &current->slots[i];
        const DisplayStatusSlot *last_slot = &last->slots[i];
        bool value_changed = Display_StatusSlotValueChanged(current_slot, last_slot);

        if (value_changed) {
            current_slot->highlight_visible = true;
            current_slot->highlight_until_tick = now + DISPLAY_VALUE_HIGHLIGHT_MS;
        } else if (Display_IsStatusHighlightActive(last_slot, now)) {
            current_slot->highlight_visible = true;
            current_slot->highlight_until_tick = last_slot->highlight_until_tick;
        } else {
            current_slot->highlight_visible = false;
            current_slot->highlight_until_tick = 0U;
        }

        if (value_changed ||
            current_slot->highlight_visible ||
            last_slot->highlight_visible) {
            Display_ClearStatusSlotValueArea(current_slot);
        }
    }
}

/**
 * @brief 全量绘制状态快照并保存为当前活动快照。
 *
 * @param snapshot 可写 CPU3 状态页快照；函数追加或读取固定槽位中的文字、数值、位置、反显和数据新鲜度，最终用于全量或差量绘制。
 */
static bool Display_DrawStatusFull(DisplayStatusSnapshot *snapshot)
{
    uint8_t i;

    if (snapshot == NULL) {
        return false;
    }

    for (i = 0U; i < snapshot->slot_count; i++) {
        snapshot->slots[i].highlight_visible = false;
        snapshot->slots[i].highlight_until_tick = 0U;
    }

    if (!Display_ClearBeforeDraw()) {
        return false;
    }
    display_status_active_snapshot = *snapshot;
    display_status_full_redraw_required = false;
    oled_equipment();
    return true;
}

/**
 * @brief 比较前后快照，只重绘发生变化的状态槽。
 *
 * @param current 本次准备显示的当前状态页快照。
 * @param last 上一次保存的值、状态或快照。
 */
static void Display_DrawStatusDelta(DisplayStatusSnapshot *current,
                                    const DisplayStatusSnapshot *last)
{
    uint8_t i;

    if (current == NULL) {
        return;
    }

    Display_UpdateStatusHighlights(current, last);
    display_status_active_snapshot = *current;
    DIS_Equipment();
    for (i = 0U; i < current->slot_count; i++) {
        DisplayStatusSlot *slot = &current->slots[i];
        const DisplayStatusSlot *last_slot = &last->slots[i];
        bool redraw_slot = Display_StatusSlotValueChanged(slot, last_slot) ||
                           slot->highlight_visible ||
                           last_slot->highlight_visible;

        if (redraw_slot) {
            uint8_t shift = Display_IsStatusHighlightActive(slot, HAL_GetTick()) ? 1U : 0U;
            Display_DrawStatusSlotValue(slot, shift);
        }
    }
}

/**
 * @brief 非采样刷新时重画状态行并恢复反白区域，不重新采样状态页数值。
 */
static void Display_DrawStatusHighlightRestore(void)
{
    uint8_t i;
    uint32_t now = HAL_GetTick();
    bool any_restored = false;

    DIS_Equipment();

    for (i = 0U; i < display_status_active_snapshot.slot_count; i++) {
        DisplayStatusSlot *slot = &display_status_active_snapshot.slots[i];

        if (slot->highlight_visible &&
            !Display_StatusTickBefore(now, slot->highlight_until_tick)) {
            Display_ClearStatusSlotValueArea(slot);
            slot->highlight_visible = false;
            slot->highlight_until_tick = 0U;
            Display_DrawStatusSlotValue(slot, 0U);
            any_restored = true;
        }
    }

    if (any_restored) {
        display_status_last_snapshot = display_status_active_snapshot;
    }
}

/**
 * @brief 存在到期反白且状态页可见时请求一次非采样刷新。
 * @return true 表示状态页有效且可见，并存在保持期刚到期的反白槽位；false 表示状态页无效、罐上操作或息屏正在占用界面，或所有反白仍在保持期内/已经清除。
 */
static bool Display_ShouldRequestStatusHighlightRefresh(void)
{
    uint8_t i;
    uint32_t now;

    if (!display_status_active_snapshot.valid ||
        FlagofTankOpera ||
        display_screen_off_active) {
        return false;
    }

    now = HAL_GetTick();
    for (i = 0U; i < display_status_active_snapshot.slot_count; i++) {
        const DisplayStatusSlot *slot = &display_status_active_snapshot.slots[i];

        if (slot->highlight_visible &&
            !Display_StatusTickBefore(now, slot->highlight_until_tick)) {
            return true;
        }
    }

    return false;
}

/**
 * @brief 按优先级查找当前应显示的活动状态槽。
 *
 * @param id 编号。该值是 CPU3 状态页固定槽位标识，用于在快照中定位同一业务字段并执行全量或差量重绘。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param is_text true 表示按文字宽度计算布局，false 表示按数值格式计算。
 * @return 成功时返回指向按优先级查找当前应显示的活动状态槽的指针；输入非法或未找到匹配项时返回 NULL。
 */
static const DisplayStatusSlot *Display_FindActiveStatusSlot(DisplayStatusSlotId id,
                                                            uint8_t row,
                                                            bool is_text)
{
    uint8_t i;

    for (i = 0U; i < display_status_active_snapshot.slot_count; i++) {
        const DisplayStatusSlot *slot = &display_status_active_snapshot.slots[i];

        if ((slot->id == id) && (slot->row == row) && (slot->is_text == is_text)) {
            return slot;
        }
    }

    return NULL;
}

/**
 * @brief 仅在匹配槽位仍处于反白期且内容一致时返回反色标志。
 *
 * @param id 编号。该值是 CPU3 状态页固定槽位标识，用于在快照中定位同一业务字段并执行全量或差量重绘。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param value 待格式化并绘制到 OLED 的数值。
 * @param is_text true 表示按文字宽度计算布局，false 表示按数值格式计算。
 * @param text 待测量、排版或写入状态槽的 NUL 结尾显示文字；宽度计算同时处理 ASCII 与中文字节。
 * @return 1 表示目标状态槽仍处于内容一致的反白保持期；槽位无效、内容变化或保持期结束时返回 0。
 */
static uint8_t Display_GetStatusSlotShift(DisplayStatusSlotId id,
                                          uint8_t row,
                                          int32_t value,
                                          bool is_text,
                                          const char *text)
{
    const DisplayStatusSlot *slot = Display_FindActiveStatusSlot(id, row, is_text);

    if ((slot == NULL) || !slot->highlight_visible) {
        return 0U;
    }

    if (is_text) {
        if ((text == NULL) || (strncmp(slot->text, text, sizeof(slot->text)) == 0)) {
            return 1U;
        }
        return 0U;
    }

    return (slot->value == value) ? 1U : 0U;
}

/**
 * @brief 根据当前前景页、恢复标志和状态快照选择局部或全量方式刷新 OLED。
 *
 * @note 罐上操作页只在监控页、恢复请求或显式重绘时刷新；状态页按布局变化选择全量绘制或差量绘制，并在每帧结束时核对 OLED SPI 错误计数。
 */
void RefreshScreen(void)
{
    uint32_t frame_spi_error_start;

    display_recover_before_draw = false;

    if (FlagofTankOpera == true) {
        if (DisplayTankOpera_IsMotorRunMonitorActive() ||
            DisplayTankOpera_IsDebugWeightWaitActive() ||
            DisplayTankOpera_IsAoRuntimeActive() ||
            DisplayTankOpera_IsCpu2CommHealthActive()) {
            if (!Display_PrepareForForegroundDraw(&frame_spi_error_start)) {
                return;
            }
            if (DisplayTankOpera_RedrawCurrentPage()) {
                Display_FinishFrame(frame_spi_error_start);
            }
            return;
        }
        if (Display_ShouldRecoverBeforeDraw()) {
            frame_spi_error_start = Display_BeginFrame();
            if (Display_PerformRecovery() && DisplayTankOpera_RedrawCurrentPage()) {
                Display_FinishFrame(frame_spi_error_start);
            }
        }
        return;
    }

    if(ScreenOff()) {
        if (!display_screen_off_active) {
            frame_spi_error_start = Display_BeginFrame();
            OLED_DisplayOff();
            display_screen_off_active = true;
            Display_FinishFrame(frame_spi_error_start);
        }
    }
    else
    {
        frame_spi_error_start = Display_BeginFrame();
        if (display_screen_off_active) {
            OLED_DisplayOn();
            Display_RequestRecovery();
            display_screen_off_active = false;
        }
        SetScreenOffState();
        display_recover_before_draw = Display_ShouldRecoverBeforeDraw();
        /* 首次状态和当前连接协议快照完成前保持通讯尝试页，第十次失败后由故障页接管。 */
        if (CPU2_CommShouldShowStartup())
            EquipFirstPower();
        else
            oled_workingdata();
        display_recover_before_draw = false;
        Display_FinishFrame(frame_spi_error_start);
    }
}
/**
 * @brief 根据设备状态、结果上下文和当前分页，绘制状态标题、故障详情及有效测量与调试数据。
 *
 * 先绘制当前设备状态；无线配对进行中不追加测量数据，配对结束时单独显示成功取得的 MAC 或不可用提示。
 * 普通状态页按 ValidParaDisArr 的有效标志和页码，选择显示故障原因、液位、水位、密度、温度、位置、扭力、扭力模块温度、频率、电容、姿态角、罐高、无线 RSSI 和从机 MAC。
 * 各数据项使用当前测量结果上下文选择来源，并通过状态槽位计算差量绘制偏移和工程单位。
 */
static void oled_equipment(void)
{
    u8 row = OLED_ROW4_2,line = 0;
    DisplayResultContext ctx = Display_GetResultContext(g_measurement.device_status.device_state);
    int now_page = display_status_active_snapshot.page;
    uint32_t display_value = 0U;
    int display_position = 0;
    int display_frequency = 0;
    int display_capacitance = 0;
    int32_t torque_temperature_x100;
    
    /* 显示当前设备状态 */
    DIS_Equipment();

    if (g_measurement.device_status.device_state == STATE_WIRELESS_PAIRING) {
        return;
    }

    if (g_measurement.device_status.device_state == STATE_WIRELESS_PAIRING_OVER) {
        const volatile WirelessPairingStatus *status = &g_measurement.wireless_pairing_status;

        if ((status->result == WIRELESS_PAIRING_RESULT_SUCCESS) && (status->mac_valid != 0U)) {
            char mac_line1[9];
            char mac_line2[9];

            Display_FormatWirelessPairingMac(status, mac_line1, mac_line2);
            OledDisplayLineWords("MAC:", OLED_LINE8_1, OLED_ROW4_2, 0);
            OledDisplayLineWords(mac_line1,
                                 OLED_LINE8_2,
                                 OLED_ROW4_3,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_MAC_1,
                                                            OLED_ROW4_3,
                                                            0,
                                                            true,
                                                            mac_line1));
            OledDisplayLineWords(mac_line2,
                                 OLED_LINE8_2,
                                 OLED_ROW4_4,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_MAC_2,
                                                            OLED_ROW4_4,
                                                            0,
                                                            true,
                                                            mac_line2));
        } else {
            OledDisplayLineWords("MAC N/A",
                                 OLED_LINE8_2,
                                 OLED_ROW4_2,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_MAC_NA,
                                                            OLED_ROW4_2,
                                                            0,
                                                            true,
                                                            "MAC N/A"));
        }
        return;
    }

    /* 故障详情 */
    if (ValidParaDisArr[Para_ErrorReason][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_ErrorReason][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_ErrorReason][PARA_X];
        Display_ErrorReasonLine(row);
    }

    /* 故障原因确实占用第二行且该槽位位于当前页时，再绘制续行，避免覆盖后续状态字段。 */
    if (ValidParaDisArr[Para_ErrorReasonMore][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_ErrorReasonMore][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_ErrorReasonMore][PARA_X];
        Display_ErrorReasonMoreLine(row);
    }

    /* 液位 */
    if(flagofoillevelvalid == true)
    {
        if(FlagofTotalTwoRow == true)
            row = OLED_ROW4_3;
        else
            row = OLED_ROW4_2;
        line = DisplayLangaugeLineWords((u8*)"液位:",OLED_LINE8_1,row,0,(u8*)"Level:");
        if (Display_GetOilLevelValue(ctx, &display_value) &&
            ((display_value == OILLEVELDOWNLIMIT) || (display_value == LEVEL_DOWNLIMIT)))
        {
            const char *text = Display_SelectLanguageText((uint8_t*)"低于盲区",
                                                          (uint8_t*)"Below Blind");
            DisplayLangaugeLineWords((u8*)"低于盲区",
                                     line,
                                     row,
                                     Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_OIL_LEVEL,
                                                                row,
                                                                0,
                                                                true,
                                                                text),
                                     (u8*)"Below Blind");
        }
        else
        {
            OledValueDisplay((int)display_value,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_OIL_LEVEL,
                                                        row,
                                                        (int32_t)display_value,
                                                        false,
                                                        NULL),
                             1,
                             (u8*)"mm");
        }
    }
    /* 水位 */
    if(ValidParaDisArr[Para_Waterlevel][PARA_VALID] == true && now_page == ValidParaDisArr[Para_Waterlevel][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_Waterlevel][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"水位:",OLED_LINE8_1,row,0,(u8*)"Water:");
        if (Display_GetWaterLevelValue(ctx, &display_value))
        {
            OledValueDisplay((int)display_value,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WATER_LEVEL,
                                                        row,
                                                        (int32_t)display_value,
                                                        false,
                                                        NULL),
                             1,
                             (u8*)"mm");
        }
    }
    /* 密度 */
    if(ValidParaDisArr[Para_AveDensity][PARA_VALID] == true && now_page == ValidParaDisArr[Para_AveDensity][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_AveDensity][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"密度:",OLED_LINE8_1,row,0,(u8*)"D:");
        if (Display_GetDensityValue(ctx, &display_value))
        {
            OledValueDisplay((int)display_value,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_DENSITY,
                                                        row,
                                                        (int32_t)display_value,
                                                        false,
                                                        NULL),
                             2,
                             (u8*)"kg/m3");
        }
    }
    /* 温度 */
    if(ValidParaDisArr[Para_AveTemperature][PARA_VALID] == true && now_page == ValidParaDisArr[Para_AveTemperature][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_AveTemperature][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"温度:",OLED_LINE8_1,row,0,(u8*)"Temp:");
        if (Display_GetTemperatureValue(ctx, &display_value))
        {
            OledValueDisplay((int)display_value - 20000,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_TEMPERATURE,
                                                        row,
                                                        (int32_t)display_value - 20000,
                                                        false,
                                                        NULL),
                             2,
                             (u8*)"℃");
        }
    }
 
    /* 位置 */
    if(ValidParaDisArr[Para_position][PARA_VALID] == true && now_page == ValidParaDisArr[Para_position][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_position][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"位置:",OLED_LINE8_1,row,0,(u8*)"Pos:");
        if (Display_GetPositionValue(ctx, &display_position))
        {
            OledValueDisplay(display_position,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_POSITION,
                                                        row,
                                                        (int32_t)display_position,
                                                        false,
                                                        NULL),
                             1,
                             (u8*)"mm");
        }
    }
    /* 扭力 */
	if (ValidParaDisArr[Para_weight][PARA_VALID] == true && now_page == ValidParaDisArr[Para_weight][PARA_PAGE]) {
		row = ValidParaDisArr[Para_weight][PARA_X];
		line = DisplayLangaugeLineWords((u8*) "扭力:", OLED_LINE8_1, row, 0, (u8*) "Torque:");
		OledValueDisplay(g_measurement.debug_data.current_weight,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WEIGHT,
                                                    row,
                                                    (int32_t)g_measurement.debug_data.current_weight,
                                                    false,
                                                    NULL),
                         0,
                         (u8*) " ");
	}
    /* 扭力模块温度 */
    if (ValidParaDisArr[Para_torque_temperature][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_torque_temperature][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_torque_temperature][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"扭温:", OLED_LINE8_1, row, 0, (u8*)"T.Temp:");
        if (Display_GetTorqueTemperatureX100(ctx, &torque_temperature_x100))
        {
            OledValueDisplay((int)torque_temperature_x100,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_TORQUE_TEMPERATURE,
                                                        row,
                                                        torque_temperature_x100,
                                                        false,
                                                        NULL),
                             2,
                             (u8*)"℃");
        }
        else
        {
            OledDisplayLineWords("--.--",
                                 line,
                                 row,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_TORQUE_TEMPERATURE,
                                                            row,
                                                            0,
                                                            true,
                                                            "--.--"));
        }
    }
    /* 频率 */
    if (ValidParaDisArr[Para_sensor_value][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_sensor_value][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_sensor_value][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"频率:", OLED_LINE8_1, row, 0, (u8*)"Freq:");
        display_frequency = (ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
            ? (int)g_measurement.debug_data.frequency
            : GetOilSensorFrequencyForDisplay();
        OledValueDisplay(display_frequency,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_FREQUENCY,
                                                    row,
                                                    (int32_t)display_frequency,
                                                    false,
                                                    NULL),
                         0,
                         (u8*)"Hz");
    }

    /* 电容 */
    if (ValidParaDisArr[Para_capacitance][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_capacitance][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_capacitance][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"电容:", OLED_LINE8_1, row, 0, (u8*)"Cap:");
        display_capacitance = (ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
            ? (int)g_measurement.debug_data.water_capacitance_x10
            : (int)(g_measurement.water_measurement.current_capacitance * 10.0f);
        OledValueDisplay(display_capacitance,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_CAPACITANCE,
                                                    row,
                                                    (int32_t)display_capacitance,
                                                    false,
                                                    NULL),
                         1,
                         NULL);
    }
    /* 陀螺仪角度 X */
    if (ValidParaDisArr[Para_angle_x][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_angle_x][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_angle_x][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"X角:", OLED_LINE8_1, row, 0, (u8*)"AngX:");
        OledValueDisplay(g_measurement.debug_data.angle_x,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_ANGLE_X,
                                                    row,
                                                    (int32_t)g_measurement.debug_data.angle_x,
                                                    false,
                                                    NULL),
                         2,
                         (u8*)"°");
    }

    /* 陀螺仪角度 Y */
    if (ValidParaDisArr[Para_angle_y][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_angle_y][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_angle_y][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"Y角:", OLED_LINE8_1, row, 0, (u8*)"AngY:");
        OledValueDisplay(g_measurement.debug_data.angle_y,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_ANGLE_Y,
                                                    row,
                                                    (int32_t)g_measurement.debug_data.angle_y,
                                                    false,
                                                    NULL),
                         2,
                         (u8*)"°");
    }
    /* 罐高显示 */
    if (ValidParaDisArr[Para_tankheight][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_tankheight][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_tankheight][PARA_X];
        line = DisplayLangaugeLineWords((u8*)"罐高:", OLED_LINE8_1, row, 0, (u8*)"tankH:");
        OledValueDisplay(g_measurement.height_measurement.current_real_height,
                         line,
                         row,
                         Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_TANK_HEIGHT,
                                                    row,
                                                    (int32_t)g_measurement.height_measurement.current_real_height,
                                                    false,
                                                    NULL),
                         1,
                         (u8*)"mm");
    }
    /* 蓝牙连接 RSSI */
    if (ValidParaDisArr[Para_wireless_rssi][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_wireless_rssi][PARA_PAGE])
    {
        row = ValidParaDisArr[Para_wireless_rssi][PARA_X];
        if (g_measurement.wireless_pairing_status.rssi_valid != 0U)
        {
            line = DisplayLangaugeLineWords((u8*)"RSSI:", OLED_LINE8_1, row, 0, (u8*)"RSSI:");
            OledValueDisplay((int)g_measurement.wireless_pairing_status.rssi,
                             line,
                             row,
                             Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_RSSI,
                                                        row,
                                                        g_measurement.wireless_pairing_status.rssi,
                                                        false,
                                                        NULL),
                             0,
                             (u8*)"dB");
        }
        else
        {
            OledDisplayLineWords("RSSI:N/A",
                                 OLED_LINE8_1,
                                 row,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_RSSI_NA,
                                                            row,
                                                            0,
                                                            true,
                                                            "RSSI:N/A"));
        }
    }
    /* 连接从机蓝牙 MAC */
    if (ValidParaDisArr[Para_wireless_mac][PARA_VALID] == true &&
        now_page == ValidParaDisArr[Para_wireless_mac][PARA_PAGE])
    {
        const volatile WirelessPairingStatus *status = &g_measurement.wireless_pairing_status;

        row = ValidParaDisArr[Para_wireless_mac][PARA_X];
        if ((status->connection_valid != 0U) && (status->mac_valid != 0U))
        {
            char mac_line[17];

            Display_FormatWirelessConnectionMacCompact(status, mac_line, sizeof(mac_line));
            OledDisplayLineWords(mac_line,
                                 OLED_LINE8_1,
                                 row,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_MAC_COMPACT,
                                                            row,
                                                            0,
                                                            true,
                                                            mac_line));
        }
        else
        {
            OledDisplayLineWords("MAC N/A",
                                 OLED_LINE8_1,
                                 row,
                                 Display_GetStatusSlotShift(DISPLAY_STATUS_SLOT_WIRELESS_MAC_NA,
                                                            row,
                                                            0,
                                                            true,
                                                            "MAC N/A"));
        }
    }
}
/**
 * @brief 显示多个汉字或字符 - 带中英文选择。
 *
 * @param name1 中文模式使用的显示文字。
 * @param line OLED 绘制使用的横向列位置。
 * @param row OLED 绘制使用的行号。取值使用 OLED_ROW4_x 等页面行坐标常量，决定文字或数字写入的纵向基线。
 * @param shift OLED 字模阴码/阳码或显示偏移选项。
 * @param name2 英文模式使用的显示文字；为 NULL 时沿用中文文字。
 * @return 返回当前语言文本绘制完成后的下一 OLED 横坐标；英文文本为空时使用中文文本。
 */
uint8_t DisplayLangaugeLineWords(uint8_t* name1,uint8_t line,uint8_t row,uint8_t shift,uint8_t* name2)
{
    if(screen_parameter.language == LANGUAGE_CHINESE || name2 == NULL)
        line = OledDisplayLineWords(name1,line,row,shift);
    else if(screen_parameter.language == LANGUAGE_ENGLISH)
        line = OledDisplayLineWords(name2,line,row,shift);
    return line;
}

/**
 * @brief 根据当前测量结果上下文生成 OLED 结果页的有效参数布局。
 *
 * 函数先根据设备状态取得结果页上下文，再逐项判定故障详情、液位、密度、温度、水位、位置、扭力、部件参数、传感器原始量、姿态角、罐高和无线信息是否需要显示。
 * 每个有效项目按显示顺序写入 ValidParaDisArr 的 PARA_NUM 和 PARA_VALID；需要两行的故障原因会占用两个连续项目，读取部件参数时为扭力模块温度、RSSI 和 MAC
 * 保留固定项目。
 * 液位有效时结果区每页排两行并从 OLED_ROW4_3 开始，否则每页排三行并从 OLED_ROW4_2 开始；随后计算 PageAmount 以及每个有效项目的页号和行坐标。
 *
 * @note 函数直接更新 ValidParaDisArr、PageAmount、FlagofTotalTwoRow 和液位有效标志，调用方应在测量快照更新后再生成页面布局。
 */
static void CalculateValidPara(void)
{
    static int ValidParaCnt = 0; /* 需要显示的有效参数 */
    static u8 start_x = 0;
    static int rowsperpage = 2;
    int i;
    DisplayResultContext ctx = Display_GetResultContext(g_measurement.device_status.device_state);
    uint32_t display_value = 0U;
    int display_position = 0;
    
    /* *****计算总共有多少个有效参数需要显示***** */
    ValidParaCnt = 0;
    /* 故障详情 */
    if (Display_ShouldShowErrorReason(ctx))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_ErrorReason][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_ErrorReason][PARA_VALID] = true;
        /* 长故障原因需要两个状态槽位；短原因只登记首行，并显式关闭旧页面残留的续行槽位。 */
        if (Display_IsErrorReasonNeedTwoRows())
        {
            ValidParaCnt++;
            ValidParaDisArr[Para_ErrorReasonMore][PARA_NUM] = ValidParaCnt;
            ValidParaDisArr[Para_ErrorReasonMore][PARA_VALID] = true;
        }
        else
        {
            ValidParaDisArr[Para_ErrorReasonMore][PARA_VALID] = false;
        }
    }
    else
    {
        ValidParaDisArr[Para_ErrorReason][PARA_VALID] = false;
        ValidParaDisArr[Para_ErrorReasonMore][PARA_VALID] = false;
    }
    /* 液位 */
    flagofoillevelvalid = Display_ShouldShowOilLevel(ctx);
    /* 密度 */
    if(Display_GetDensityValue(ctx, &display_value))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_AveDensity][PARA_NUM] = ValidParaCnt;
		
        ValidParaDisArr[Para_AveDensity][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_AveDensity][PARA_VALID] = false;
    /* 温度 */
    if(Display_GetTemperatureValue(ctx, &display_value))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_AveTemperature][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_AveTemperature][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_AveTemperature][PARA_VALID] = false;
    /* 水位 */
    if(Display_ShouldShowWaterLevel(ctx))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_Waterlevel][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_Waterlevel][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_Waterlevel][PARA_VALID] = false;
  
    /* 位置 */
    if(Display_GetPositionValue(ctx, &display_position))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_position][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_position][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_position][PARA_VALID] = false;
    /* 扭力 */
    if(Display_ShouldShowWeight(ctx))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_weight][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_weight][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_weight][PARA_VALID] = false;
    /* 扭力模块温度在读取部件参数结果页固定占一项，无效时显示占位。 */
    if (ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_torque_temperature][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_torque_temperature][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_torque_temperature][PARA_VALID] = false;
    /* 频率 */
    if (Display_ShouldShowOilFrequencyValue(ctx))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_sensor_value][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_sensor_value][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_sensor_value][PARA_VALID] = false;
    /* 电容 */
    if (Display_ShouldShowWaterCapacitanceValue(ctx))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_capacitance][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_capacitance][PARA_VALID] = true;
    }
    else
        ValidParaDisArr[Para_capacitance][PARA_VALID] = false;
    /* 陀螺仪角度 X */
    if (((ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER) ||
         ((ctx == DISPLAY_RESULT_CONTEXT_BOTTOM_HEIGHT) && IsBottomAngleDisplayEnabled())) &&
        (g_measurement.debug_data.angle_x != 0))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_angle_x][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_angle_x][PARA_VALID] = true;
    }
    else {
        ValidParaDisArr[Para_angle_x][PARA_VALID] = false;
    }

    /* 陀螺仪角度 Y */
    if (((ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER) ||
         ((ctx == DISPLAY_RESULT_CONTEXT_BOTTOM_HEIGHT) && IsBottomAngleDisplayEnabled())) &&
        (g_measurement.debug_data.angle_y != 0))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_angle_y][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_angle_y][PARA_VALID] = true;
    }
    else {
        ValidParaDisArr[Para_angle_y][PARA_VALID] = false;
    }
    /* 罐高 */
    /* 读取参数态不展示历史罐高，避免把上一次业务结果误认为本次部件参数。 */
    if ((g_measurement.height_measurement.current_real_height != 0) &&
        ((g_measurement.device_status.device_state == STATE_FINDBOTTOM_OVER) ||
         (g_measurement.device_status.device_state == STATE_CALIBRATE_TANKHEIGHT_OVER)))
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_tankheight][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_tankheight][PARA_VALID] = true;
    }
    else {
        ValidParaDisArr[Para_tankheight][PARA_VALID] = false;
    }
    /* 蓝牙连接 RSSI */
    if (ctx == DISPLAY_RESULT_CONTEXT_READ_PARAMETER)
    {
        ValidParaCnt++;
        ValidParaDisArr[Para_wireless_rssi][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_wireless_rssi][PARA_VALID] = true;
        ValidParaCnt++;
        ValidParaDisArr[Para_wireless_mac][PARA_NUM] = ValidParaCnt;
        ValidParaDisArr[Para_wireless_mac][PARA_VALID] = true;
    }
    else {
        ValidParaDisArr[Para_wireless_rssi][PARA_VALID] = false;
        ValidParaDisArr[Para_wireless_mac][PARA_VALID] = false;
    }
    #if DEBUG_DISPLAY
    printf("ValidParaCnt = %d\n",ValidParaCnt);
    #endif
    /* *****计算总共需用几页,以及起始行***** */
    if(flagofoillevelvalid == true)
    {
        rowsperpage = 2;
        PageAmount = ceil(ValidParaCnt / (float)rowsperpage);
        start_x = OLED_ROW4_3;
    }
    else
    {
        rowsperpage = 3;
        PageAmount = ceil(ValidParaCnt / (float)rowsperpage);
        start_x = OLED_ROW4_2;
    }
    #if DEBUG_DISPLAY
    printf("rowsperpage = %d\n",rowsperpage);
    printf("PageAmount = %d\n",PageAmount);
    printf("start_x = %d\n",start_x);
    #endif
    /* *****计算每一个参数对应的行号和页号***** */
    if(PageAmount == 0 && rowsperpage == 2) /* 特殊情况:一共只显示两行的情况下这两行要居中显示 */
    {
        FlagofTotalTwoRow = true;
    }
    else
    {
        FlagofTotalTwoRow = false;
        for(i = 0;i<Para_Amount;i++)
        {
            ValidParaDisArr[i][PARA_X] = ((ValidParaDisArr[i][PARA_NUM] - 1) % rowsperpage ) * (OLED_ROW4_2 - OLED_ROW4_1) + start_x;
            ValidParaDisArr[i][PARA_PAGE] = (ValidParaDisArr[i][PARA_NUM] - 1) / rowsperpage;
            #if DEBUG_DISPLAY
            printf("%d\tx = %d\tpage = %d\tnum = %d\n",i,ValidParaDisArr[i][PARA_X],ValidParaDisArr[i][PARA_PAGE],ValidParaDisArr[i][PARA_NUM]);
            #endif
        }
    }
}
